From e3741380f2ab810805d8513b0774678036d68080 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:19:12 +0100
Subject: [PATCH] startkde: take the first LANG from the systemd user
 environment

Display managers like SDDM can start the session with the system LANG,
so on first login that value was saved to plasma-localerc instead of the
user locale from environment.d. Prefer systemd's LANG when one is set.

BUG: 497501
---
 startkde/startplasma.cpp | 15 ++++++++++++---
 1 file changed, 12 insertions(+), 3 deletions(-)

diff --git a/startkde/startplasma.cpp b/startkde/startplasma.cpp
index 9cda0be1e5..64e23b0a99 100644
--- a/startkde/startplasma.cpp
+++ b/startkde/startplasma.cpp
@@ -217,9 +217,18 @@ void runStartupConfig()
         qputenv("LANGUAGE", value.toUtf8());
     }

-    if (!formatsConfig.hasKey("LANG") && !qEnvironmentVariableIsEmpty("LANG")) {
-        formatsConfig.writeEntry("LANG", qgetenv("LANG"));
-        formatsConfig.sync();
+    if (!formatsConfig.hasKey("LANG")) {
+        // The display manager may have started us with a different LANG than the one
+        // the user's session gets from environment.d, so prefer systemd's value
+        const auto systemdEnvironment = getSystemdEnvironment();
+        const QString systemdLang = systemdEnvironment ? systemdEnvironment->value(QStringLiteral("LANG")) : QString();
+        if (!systemdLang.isEmpty()) {
+            qputenv("LANG", systemdLang.toUtf8());
+        }
+        if (!qEnvironmentVariableIsEmpty("LANG")) {
+            formatsConfig.writeEntry("LANG", qgetenv("LANG"));
+            formatsConfig.sync();
+        }
     }
 }

